/// Whole stored transcript: banded prompts, markdown answers, one blank row
/// between turns.
pub fn transcript_rows(body: &[String], width: usize) -> Vec<Row> {
    let parsed = transcript(body);
    let mut rows: Vec<Row> = Vec::with_capacity(parsed.len() * 4);
    let mut index = 0;
    while index < parsed.len() {
        if !rows.is_empty() {
            rows.push(Row::new());
        }
        match parsed[index].role {
            Role::User => {
                for (line, text) in parsed[index].text.split('\n').enumerate() {
                    let first = run(if line == 0 { "> " } else { "  " }, DIM.on(NIGHT.surface));
                    rows.extend(wrap(
                        vec![first],
                        vec![run("  ", BAND)],
                        vec![run(text, BAND)],
                        width,
                        Some(BAND),
                    ));
                }
                index += 1;
            }
            Role::Assistant => {
                let mut text = String::new();
                while index < parsed.len() && parsed[index].role == Role::Assistant {
                    if !text.is_empty() {
                        text.push('\n');
                    }
                    text.push_str(&parsed[index].text);
                    index += 1;
                }
                rows.extend(answer_rows(&text, width));
            }
        }
    }
    rows
}

fn is_bar(span: &markdown::Span) -> bool {
    span.ink == Ink::Dim && span.text == "│ "
}

/// One assistant answer: `● ` marker on the first row, markdown blocks below.
pub fn answer_rows(text: &str, width: usize) -> Vec<Row> {
    let blocks = markdown::render(text, width.saturating_sub(4).max(8));
    let mut rows = Vec::new();
    let mut index = 0;
    while index < blocks.len() {
        let block = &blocks[index];
        if block.code {
            let end = blocks[index..]
                .iter()
                .position(|block| !block.code)
                .map_or(blocks.len(), |offset| index + offset);
            rows.extend(code_panel(&blocks[index..end], width, index == 0));
            index = end;
            continue;
        }
        index += 1;
        if block.spans.is_empty() {
            rows.push(Row::new());
            continue;
        }
        let marker = if index == 1 {
            run("● ", ACCENT)
        } else {
            run("  ", TEXT)
        };
        // Wrapped list items hang under their text, not under the bullet.
        let bullet = match block.spans.first() {
            Some(span)
                if span.ink == Ink::Dim && span.text.ends_with(' ') && span.text.len() <= 5 =>
            {
                span.text.width()
            }
            _ => 0,
        };
        // Quote bars repeat on wrapped rows; bullets and numbers do not.
        let quote: Row = block
            .spans
            .iter()
            .take_while(|span| is_bar(span))
            .map(|span| run(span.text.clone(), ink(span.ink)))
            .collect();
        let hang = if quote.is_empty() {
            vec![run(" ".repeat(2 + block.indent + bullet), TEXT)]
        } else {
            let mut hang = vec![run(" ".repeat(2 + block.indent), TEXT)];
            hang.extend(quote);
            hang
        };
        let body = block
            .spans
            .iter()
            .map(|span| run(span.text.clone(), ink(span.ink)))
            .collect();
        let first = vec![marker, run(" ".repeat(block.indent), TEXT)];
        rows.extend(wrap(first, hang, body, width, None));
    }
    rows
}

/// One fenced block as a panel: language label row, then the code lines,
/// numbered when there are 3+. Wrapped lines hang under the code.
fn code_panel(blocks: &[Block], width: usize, first: bool) -> Vec<Row> {
    let surface = Paint::fg(NIGHT.text).on(NIGHT.surface);
    let bars = blocks[0]
        .spans
        .iter()
        .take_while(|span| is_bar(span))
        .count();
    // Everything left of the panel: answer marker, list indent, quote bars.
    let mut outside = vec![
        run(if first { "● " } else { "  " }, ACCENT),
        run(" ".repeat(blocks[0].indent), TEXT),
    ];
    outside.extend((0..bars).map(|_| run("│ ", DIM)));
    let mut blank = outside.clone();
    blank[0] = run("  ", TEXT);

    let label: String = blocks[0].spans[bars..]
        .iter()
        .map(|span| span.text.as_str())
        .collect();
    let code = &blocks[1..];
    let numbered = code.len() >= 3;
    let digits = if numbered {
        code.len().to_string().len()
    } else {
        0
    };
    let number = Paint::fg(NIGHT.faint).on(NIGHT.surface);

    let mut rows = Vec::with_capacity(code.len() + 1);
    let mut head = outside;
    head.push(run(format!(" {label}"), DIM.on(NIGHT.surface).italic()));
    rows.extend(wrap(head, blank.clone(), Row::new(), width, Some(surface)));
    for (line, block) in code.iter().enumerate() {
        let mut first = blank.clone();
        let mut hang = blank.clone();
        if numbered {
            first.push(run(format!(" {:>digits$}  ", line + 1), number));
            hang.push(run(format!(" {}  ", " ".repeat(digits)), number));
        } else {
            first.push(run("  ", surface));
            hang.push(run("  ", surface));
        }
        let body = block.spans[bars.min(block.spans.len())..]
            .iter()
            .map(|span| {
                let mut paint = ink(span.ink);
                paint.bg = Some(NIGHT.surface);
                run(span.text.clone(), paint)
            })
            .collect();
        rows.extend(wrap(first, hang, body, width, Some(surface)));
    }
    rows
}

/// The prompt box: `> ` then the text, wrapped with a hanging indent.
pub fn input_rows(input: &str, placeholder: &str, width: usize) -> Vec<Row> {
    let body = if input.is_empty() {
        vec![run(placeholder, DIM)]
    } else {
        vec![run(input, TEXT), run("▏", ACCENT)]
    };
    wrap(
        vec![run("> ", ACCENT)],
        vec![run("  ", TEXT)],
        body,
        width,
        None,
    )
}

/// `left` and `right` on one row of `width`; `left` is cut at ` · `
/// boundaries so a hint is shown whole or not at all.
pub fn status_row(left: &str, left_paint: Paint, right: &str, width: usize) -> Row {
    let right = clip(right, width);
    let room = width.saturating_sub(right.width() + 2);
    let mut shown = String::new();
    for item in left.split(" · ") {
        let next = if shown.is_empty() {
            item.to_string()
        } else {
            format!("{shown} · {item}")
        };
        if next.width() > room {
            break;
        }
        shown = next;
    }
    let gap = width.saturating_sub(shown.width() + right.width());
    vec![
        run(shown, left_paint),
        run(" ".repeat(gap), DIM),
        run(right, DIM),
    ]
}

    /// Lay out one screen of `cols` × `rows` cells.
    pub fn frame(&mut self, cols: usize, rows: usize) -> Frame {
        let cols = cols.max(10);
        let view = self.client.view();
        // One column of air on the right of the transcript.
        let width = cols - 1;
        let fresh = self
            .cache
            .as_ref()
            .is_some_and(|cache| cache.version == self.version && cache.width == width);
        if !fresh {
            self.cache = Some(Cache {
                version: self.version,
                width,
                rows: layout::transcript_rows(&view.transcript, width),
                has_code: view
                    .transcript
                    .iter()
                    .any(|line| line.trim_start().starts_with("```")),
            });
        }
        let Some(cache) = self.cache.as_ref() else {
            unreachable!("cache was just filled");
        };

        let mut input = layout::input_rows(&self.input, "type a message", width);
        let keep = input.len().clamp(1, 6);
        input.drain(..input.len() - keep);
        let viewport = rows.saturating_sub(2 + input.len());

        // Live tail: the streaming answer or the spinner, after the stored rows.
        let mut tail: Vec<Row> = Vec::new();
        if !self.streaming.is_empty() {
            if !cache.rows.is_empty() {
                tail.push(Row::new());
            }
            tail.extend(layout::answer_rows(&self.streaming, width));
        } else if let Some(elapsed) = self.clock.running_secs() {
            if !cache.rows.is_empty() {
                tail.push(Row::new());
            }
            tail.push(vec![run(
                format!("✻ {}… ({elapsed:.0}s)", spinner_word(elapsed)),
                DIM,
            )]);
        }
        let total = cache.rows.len() + tail.len();
        self.viewport = viewport;
        self.max_scroll = total.saturating_sub(viewport);
        self.scroll = self.scroll.min(self.max_scroll);
        // History grows upward from the input: pad the top, never the bottom.
        let end = total - self.scroll;
        let start = end.saturating_sub(viewport);
        let mut screen: Vec<Row> = vec![Row::new(); viewport - (end - start)];
        screen.extend(
            cache
                .rows
                .iter()
                .chain(tail.iter())
                .skip(start)
                .take(end - start)
                .cloned(),
        );

        screen.push(vec![run("─".repeat(cols), Paint::fg(NIGHT.faint))]);
        screen.extend(input);
        screen.push(self.status(cols, cache.has_code, &view));
        Frame {
            rows: screen,
            picker: (self.mode == Mode::Picker).then(|| PickerView {
                title: format!("sessions {}", self.picker.counter()),
                query: self.picker.query.clone(),
                items: self
                    .picker
                    .visible(PICKER_ROWS)
                    .into_iter()
                    .map(|(index, item)| (item.label.clone(), index == self.picker.index()))
                    .collect(),
            }),
        }
    }

    fn status(&self, cols: usize, has_code: bool, view: &smash_core::View) -> Row {
        let typing = match self.mode {
            Mode::Picker => self.picker.query_typed(),
            Mode::Chat => !self.input.is_empty(),
        };
        let session = view
            .rows
            .iter()
            .find(|row| row.selected)
            .map_or("no session", |row| row.text.as_str());
        // Narrow screens keep the key hints; the model name goes first.
        let model = if cols >= 72 {
            format!(" · {}", self.model)
        } else {
            String::new()
        };
        let clock = self.clock.label();
        let clock = if clock.is_empty() {
            clock
        } else {
            format!(" · {clock}")
        };
        let right = format!("│  {session}{model}{clock}");
        if let Some(notice) = &self.notice {
            let paint = if notice.starts_with('✓') {
                ACCENT
            } else {
                Paint::fg(NIGHT.code)
            };
            return layout::status_row(notice, paint, &right, cols);
        }
        let mut hint = hints(self.mode, typing, self.clock.generating()).to_string();
        if self.max_scroll > 0 && self.mode == Mode::Chat && !typing {
            hint = format!(
                "{} · {hint}",
                if self.scroll > 0 {
                    "↓ newer"
                } else {
                    "↑ older"
                }
            );
        }
        // Contextual hints first: they change, so they must survive truncation.
        if has_code && self.mode == Mode::Chat && !typing {
            hint = format!("ctrl+y copy code · {hint}");
        }
        layout::status_row(&hint, DIM, &right, cols)
    }
}
